def neuron_available() -> bool:
    try:
        torch.device("neuron")
        return True
    except Exception:
        return False


def detect_device_type(requested: str = "") -> str:
    """train_gpu.py (P04): cuda or cpu only. A neuron request, or a box where only neuron is available,
    is refused: the GPU proxy exists to run this file somewhere that is not Trainium."""
    if requested == "neuron":
        raise SystemExit("train_gpu.py runs on cuda or cpu only (--device cuda|cpu); use the submission train.py on Trainium")
    if requested:
        return requested
    if torch.cuda.is_available():
        return "cuda"
    if neuron_available():
        raise SystemExit("train_gpu.py: no CUDA device and torch reports a neuron device: this is the Trainium box; "
                         "pass --device cpu if a CPU smoke test is really what you want")
    return "cpu"


def init_runtime(device_type: str):
    assert device_type in {"cpu", "cuda", "neuron"}
    torch.manual_seed(SEED)
    ddp, rank, local_rank, world_size = get_dist_info()
    if ddp and device_type == "cuda":
        device = torch.device("cuda", local_rank)
        torch.cuda.set_device(device)
        dist.init_process_group("nccl", device_id=device)
    elif ddp and device_type == "neuron":
        dist.init_process_group("neuron")
        device = torch.device("neuron")
    elif ddp:
        dist.init_process_group("gloo")
        device = torch.device("cpu")
    else:
        device = torch.device(device_type)
    if dist.is_available() and dist.is_initialized():
        dist.barrier()
    return ddp, rank, local_rank, world_size, device


def cleanup_runtime() -> None:
    if dist.is_available() and dist.is_initialized():
        dist.destroy_process_group()


def synchronize(device: torch.device) -> None:
    if device.type == "cuda":
        torch.cuda.synchronize()
    elif device.type == "neuron" and hasattr(torch, "neuron"):
        torch.neuron.synchronize()


def compute_dtype_for(device: torch.device) -> torch.dtype:
    if device.type == "cuda" and torch.cuda.is_bf16_supported():
        return torch.bfloat16
    if device.type == "neuron":
        return torch.bfloat16
    return torch.float32


@torch.no_grad()
def bf16_parameters_(model: nn.Module) -> int:
    """FF_BF16_PARAMS: master weights in bf16, as the organizers' harness keeps them.

    PARAMETERS ONLY. nn.Module.to(torch.bfloat16) would walk the buffers too; the rotary
    cos/sin tables are already built at COMPUTE_DTYPE by _precompute_rotary_embeddings and
    must stay exactly as they are (they are also non-persistent, so no checkpoint carries
    them). Walking .parameters() by hand is the whole difference.

    Assigning p.data rather than rebinding the attribute keeps every Parameter OBJECT alive,
    so setup_optimizer's groups, live_params, the EMA list and the AsyncGradSync hooks all
    still name the same objects whether this ran or not. Returns how many tensors it cast.

    Called on the host, before .to(device): the transfer then moves half the bytes.

    The tripwire: a DIMENSIONED single-element parameter is the one shape whose dtype changes
    the forward rather than just its storage, because it promotes its operand while a 0-dim
    one does not (that is the whole reason FF_LAMBDA_0D exists). The import-time assert on
    LAMBDA_0D already covers today's two -- resid_lambda and x0_lambda -- and this catches the
    next such parameter someone adds, at model-build time, instead of letting it silently
    move a whole residual stream to bf16.
    """
    n = 0
    for name, q in model.named_parameters():
        assert not (q.dim() > 0 and q.numel() == 1), (
            f"FF_BF16_PARAMS: {name} is a dimensioned single-element parameter {tuple(q.shape)}; "
            "casting it would change what the forward promotes. Make it 0-dim (FF_LAMBDA_0D=1) "
            "or exclude it here.")
        if q.dtype == torch.float32:
            q.data = q.data.to(torch.bfloat16)
            n += 1
    return n



