def config_dict(config: GPTConfig) -> dict:
    """asdict(config), minus every optional field that is still at its default."""
    d = asdict(config)
    for name, default in OPTIONAL_CONFIG_FIELDS.items():
        if d.get(name) == default:
            d.pop(name, None)
    if not d.get("bigram_rows"):
        d.pop("bigram_dim", None)
    if d.get("n_kv_heads") == d.get("n_head"):
        d.pop("n_kv_heads", None)
    return d


COMPUTE_DTYPE: torch.dtype = torch.bfloat16


def norm(x: torch.Tensor) -> torch.Tensor:
    return F.rms_norm(x, (x.size(-1),))


def key_offset_mask(config: GPTConfig) -> torch.Tensor:
    """FF_KEY_OFFSET (R8 a): [head_dim] bool, True on the key channels of the rotary pairs that turn
    less than KEY_OFFSET_MAX_RAD over a whole row: inv_freq * (sequence_len - 1) < 0.1. inv_freq is
    computed exactly as GPT._precompute_rotary_embeddings computes it (fp32, host), and
    apply_rotary_emb pairs channel i with channel i + head_dim // 2, so the mask is one
    [head_dim // 2] pattern twice. rope_base 1e5, head_dim 256, T 1024: pairs 103..127."""
    head_dim = config.n_embd // config.n_head
    freqs = torch.arange(0, head_dim, 2, dtype=torch.float32)
    inv_freq = 1.0 / (config.rope_base ** (freqs / head_dim))
    slow = inv_freq * float(config.sequence_len - 1) < config.key_offset_rad
    assert bool(slow.any()) and not bool(slow.all()), (
        f"FF_KEY_OFFSET: {int(slow.sum())} of {head_dim // 2} rotary pairs are slow at rope_base="
        f"{config.rope_base}, head_dim={head_dim}, T={config.sequence_len}; the offset needs some, not all")
    return torch.cat((slow, slow))


def softcap_offset_on(config: GPTConfig) -> bool:
    """FF_SOFTCAP_A / FF_SOFTCAP_B (R8 b): is the asymmetric cap on? Both at 0.0 is master's cap."""
    return config.softcap_a > 0.0 or config.softcap_b != 0.0


def softcap_offset(logits: torch.Tensor, config: GPTConfig) -> torch.Tensor:
    """FF_SOFTCAP_A / FF_SOFTCAP_B (R8 b): A * tanh((logits + B) / C) with C = logit_softcap and
    A = softcap_a (0.0 -> C). The ordinary heads call this; _FusedChunkedCE writes the same four ops
    inline (add, div, tanh, mul) so the two heads' forward values agree bit for bit."""
    cap = config.logit_softcap
    a = config.softcap_a if config.softcap_a > 0.0 else cap
    return a * torch.tanh((logits + config.softcap_b) / cap)



_NKI_PARTITION = 128

try:
    import nki
    import nki.language as nl
    import nki.isa as nisa

    @nki.jit
    def _relu_sq_fwd(x):
        """Fused y = relu(x)**2 for a 2-D [M, N] tensor, tiled over rows."""
        M, N = x.shape
        out = nl.ndarray((M, N), dtype=x.dtype, buffer=nl.shared_hbm)
        for t in nl.affine_range((M + _NKI_PARTITION - 1) // _NKI_PARTITION):
            rows = nl.ds(t * _NKI_PARTITION, _NKI_PARTITION)
            xb = nl.ndarray((_NKI_PARTITION, N), dtype=x.dtype, buffer=nl.sbuf)
            nisa.dma_copy(dst=xb, src=x[rows])
            rb = nl.ndarray((_NKI_PARTITION, N), dtype=x.dtype, buffer=nl.sbuf)
            nisa.tensor_scalar(dst=rb, data=xb, op0=nl.maximum, operand0=0.0)
            yb = nl.ndarray((_NKI_PARTITION, N), dtype=x.dtype, buffer=nl.sbuf)
            nisa.tensor_tensor(dst=yb, data1=rb, data2=rb, op=nl.multiply)
            nisa.dma_copy(dst=out[rows], src=yb)
        return out

    @nki.jit
    def _relu_sq_bwd(x, grad_out):
        """Backward of relu(x)**2: grad_in = grad_out * 2 * relu(x)."""
        M, N = x.shape
        out = nl.ndarray((M, N), dtype=x.dtype, buffer=nl.shared_hbm)
        for t in nl.affine_range((M + _NKI_PARTITION - 1) // _NKI_PARTITION):
            rows = nl.ds(t * _NKI_PARTITION, _NKI_PARTITION)
            xb = nl.ndarray((_NKI_PARTITION, N), dtype=x.dtype, buffer=nl.sbuf)
            nisa.dma_copy(dst=xb, src=x[rows])
            gb = nl.ndarray((_NKI_PARTITION, N), dtype=x.dtype, buffer=nl.sbuf)
            nisa.dma_copy(dst=gb, src=grad_out[rows])
            rb = nl.ndarray((_NKI_PARTITION, N), dtype=x.dtype, buffer=nl.sbuf)
            nisa.tensor_scalar(dst=rb, data=xb, op0=nl.maximum, operand0=0.0)
            two_r = nl.ndarray((_NKI_PARTITION, N), dtype=x.dtype, buffer=nl.sbuf)
            nisa.tensor_scalar(dst=two_r, data=rb, op0=nl.multiply, operand0=2.0)
            yb = nl.ndarray((_NKI_PARTITION, N), dtype=x.dtype, buffer=nl.sbuf)
            nisa.tensor_tensor(dst=yb, data1=two_r, data2=gb, op=nl.multiply)
            nisa.dma_copy(dst=out[rows], src=yb)
        return out

    class _ReluSquaredNKI(torch.autograd.Function):
        """Makes the NKI relu**2 kernel differentiable so it can train."""

        @staticmethod
        def forward(ctx, x):
            y = _relu_sq_fwd(x.reshape(-1, x.shape[-1])).reshape(x.shape)
            ctx.save_for_backward(x)
            return y

        @staticmethod
        def backward(ctx, grad_out):
            (x,) = ctx.saved_tensors
            flat_x = x.reshape(-1, x.shape[-1])
            flat_g = grad_out.reshape(-1, x.shape[-1]).contiguous()
            return _relu_sq_bwd(flat_x, flat_g).reshape(x.shape)

    _HAS_NKI = True
except Exception:
    _HAS_NKI = False

