class _Relu2Fn(torch.autograd.Function):
    """M12 FF_RELU2_FN: relu(x)**2 with the backward written out. Autograd's relu -> square saves
    relu(x) and runs pow_backward (g * (2 * s)) then threshold_backward (writes 0 where s <= 0); here the
    Function saves s = relu(x) only and returns g * (s * 2.0), one fewer op. Equal values for FINITE g
    (s * 2.0 is exact; where s == 0 the product is a zero too, its sign following g's). Where x <= 0 and
    g is inf or NaN, g * 0 is NaN where threshold_backward writes 0 (no mask, by design)."""

    @staticmethod
    def forward(ctx, x):
        s = F.relu(x)
        ctx.save_for_backward(s)
        return s.square()

    @staticmethod
    def backward(ctx, g):
        (s,) = ctx.saved_tensors
        return g * (s * 2.0)


class _LeakySq(torch.autograd.Function):
    """M12 FF_LEAKY_FORM=fn|fnm: leaky(h, a)**2 = h * s with s = leaky(h, a*a) (h > 0: h * h; h <= 0:
    h * (a*a * h)). d(h * s)/dh = 2 * s on both sides, so the backward needs s alone: the Function saves
    s, not h and leaky(h). a2 = a*a is a Python float (a trace-time constant; no aten.leaky_relu, whose
    float slope torch-mlir cannot lower). use_max: s = maximum(h, h * a2), exact for 0 < a <= 1 ('fnm');
    else r = relu(h), s = r + (h - r) * a2 ('fn'). For a power-of-two a both are bit-identical to
    leaky_relu(h, a).square() and its autograd backward except: the backward may differ by 1-2 subnormal
    ulps where |h| < 4 * 2^-126 OR |g * h| < 2^-125 (the product lands on the subnormal grid: the reference
    rounds twice, round(round(g * h) * a), this once); 'fn' at h = -0.0 gives zeros of the other sign; and
    'fn' at h = +inf gives NaN (inf - inf) where the reference gives inf. 'fnm' is exact at +-inf and NaN."""

    @staticmethod
    def forward(ctx, h, a2, use_max):
        if use_max:
            s = torch.maximum(h, h * a2)
        else:
            r = torch.relu(h)
            s = r + (h - r) * a2
        ctx.save_for_backward(s)
        return h * s

    @staticmethod
    def backward(ctx, g):
        (s,) = ctx.saved_tensors
        return g * (s * 2.0), None, None


def relu_squared(x: torch.Tensor) -> torch.Tensor:
    """relu(x)**2, via the example NKI kernel when enabled, else eager."""
    if USE_NKI_RELU2 and _HAS_NKI and x.device.type == "neuron" and (x.numel() // x.shape[-1]) % _NKI_PARTITION == 0:
        return _ReluSquaredNKI.apply(x)
    if RELU2_FN:
        return _Relu2Fn.apply(x)
    return F.relu(x).square()


