class _DispatchTrace:
    """FF_DISPATCH_TRACE: count aten ops that take a Python float or a CPU tensor, and implicit .item()."""

    def __init__(self):
        import collections
        from torch.utils._python_dispatch import TorchDispatchMode
        from torch.utils._pytree import tree_flatten
        rows = collections.Counter()
        here = __file__

        def site():
            import traceback
            fr = [f for f in traceback.extract_stack() if f.filename == here]
            return " <- ".join(f"{f.lineno}:{f.name}" for f in reversed(fr[-4:-1]))

        class _Mode(TorchDispatchMode):
            def __torch_dispatch__(self, func, types, args=(), kwargs=None):
                kwargs = kwargs or {}
                flat, _ = tree_flatten((args, kwargs))
                name = getattr(getattr(func, "overloadpacket", func), "__name__", str(func))
                pyf = any(type(a) is float for a in flat)
                cput = any(isinstance(a, torch.Tensor) and a.device.type == "cpu" for a in flat)
                if pyf or cput or name in ("_local_scalar_dense", "item", "_to_copy"):
                    rows[(name, "pyfloat" if pyf else "", "cputensor" if cput else "", site())] += 1
                return func(*args, **kwargs)

        self.rows, self.mode = rows, _Mode()

    def __enter__(self):
        self.mode.__enter__()
        return self

    def __exit__(self, *exc):
        self.mode.__exit__(*exc)
        total = sum(self.rows.values())
        print(f"===== dispatch trace, step 7 eager region, rank 0: {total} flagged ops =====", flush=True)
        for (name, pyf, cput, where), n in self.rows.most_common(90):
            print(f"{n:6d}  {name:28s} {pyf:8s} {cput:10s} {where}", flush=True)
        return False
