def _sync_probe2(device: torch.device) -> None:
    """FF_SYNC_PROBE2: timing of candidate replacements, then device bitwise comparisons."""
    def ms(t: float) -> float:
        return 1000.0 * (time.monotonic() - t)

    g = torch.Generator().manual_seed(4321)
    a_cpu = (torch.randn(4096, 4096, generator=g) / 64).to(torch.bfloat16)
    a = a_cpu.to(device)

    def chain(n: int = 48):
        y = a
        for _ in range(n):
            y = y @ a
        return y

    def run(fn):
        synchronize(device)
        t = time.monotonic()
        y = chain()
        t_q = ms(t)
        t = time.monotonic()
        fn(y)
        t_op = ms(t)
        t = time.monotonic()
        synchronize(device)
        return t_q, t_op, ms(t)

    f = torch.randn(1024, 1024, generator=g).to(device)
    g2 = torch.randn(1024, 1024, generator=g).to(device)
    s0 = torch.zeros((), device=device)
    w_t = torch.tensor(0.05, dtype=torch.float32).to(device)
    m_t = torch.tensor(1e-7, dtype=torch.float32).to(device)
    l_t = torch.tensor(-0.01, dtype=torch.float32).to(device)
    h2d_src = torch.ones(8, 1024, dtype=torch.int32)
    cases = [
        ("noop", lambda y: None),
        ("int_operand_inplace", lambda y: s0.mul_(2)),
        ("int_divide_outofplace", lambda y: s0 / 4),
        ("h2d_to_new_2d", lambda y: h2d_src.to(device)),
        ("h2d_to_new_2d_nonblocking", lambda y: h2d_src.to(device, non_blocking=True)),
        ("h2d_new_0d_tensor", lambda y: torch.tensor(0.37, dtype=torch.float32).to(device)),
        ("lerp_float_weight", lambda y: f.lerp_(g2, 0.05)),
        ("lerp_tensor_weight", lambda y: f.lerp_(g2, w_t)),
        ("addcmul_value_float", lambda y: f.addcmul_(g2, g2, value=-0.01)),
        ("addcmul_tensor", lambda y: f.addcmul_(g2, l_t)),
        ("clamp_min_float", lambda y: f.clamp_min(1e-7)),
        ("clamp_min_tensor", lambda y: f.clamp_min(m_t)),
        ("maximum_tensor", lambda y: torch.maximum(f, m_t)),
        ("add_alpha_float", lambda y: f.add_(g2, alpha=0.01)),
        ("square", lambda y: f.square()),
        ("rsub_float", lambda y: 1.0 - s0),
    ]
    for _, fn in cases:
        run(fn)
    for name, fn in cases:
        q, op, rest = sorted((run(fn) for _ in range(3)), key=lambda v: v[1])[1]
        print(f"sync_probe2 time {name:28s} op={op:7.1f}ms  drain_after={rest:7.1f}ms  (chain {q + op + rest:6.1f}ms)",
              flush=True)

    def cmp(name, x, y):
        x, y = x.detach().float().cpu(), y.detach().float().cpu()
        eq = torch.equal(x, y)
        d = (x - y).abs().max().item() if not eq else 0.0
        n = int((x != y).sum().item())
        print(f"sync_probe2 bits {name:44s} equal={eq!s:5s} ndiff={n:8d} maxdiff={d:.3e}", flush=True)

    def t32(v):
        return torch.tensor(v, dtype=torch.float32).to(device)

    def tbf(v):
        return torch.tensor(v, dtype=torch.bfloat16).to(device)

    X = torch.randn(1024, 1024, generator=g)
    X[:16] = 0.0
    X[16:32] *= 1e-8
    X = X.to(device)
    G = torch.randn(1024, 1024, generator=g).to(device)
    U = torch.randn(1024, 1024, generator=g).to(device)
    Lr = t32(0.0123)
    V = (torch.rand(1024, 1024, generator=g) * 1e-6).to(device)
    V[:8] = 0.0
    for c in (0.37, 0.9, 3.4445, -4.775, 1.01, 0.05, 0.95):
        cmp(f"fp32 X*{c} float vs t32", X * c, X * t32(c))
    cmp("fp32 X/0.9 float vs t32", X / 0.9, X / t32(0.9))
    cmp("fp32 X/(1-0.9**7) float vs t32", X / (1 - 0.9 ** 7), X / t32(1 - 0.9 ** 7))
    cmp("fp32 sqrt(V)+1e-10 float vs t32", V.sqrt() + 1e-10, V.sqrt() + t32(1e-10))
    cmp("fp32 lerp(G,0.05) Scalar vs Tensor", X.lerp(G, 0.05), X.lerp(G, t32(0.05)))
    cmp("fp32 lerp(G,0.95) Scalar vs Tensor", X.lerp(G, 0.95), X.lerp(G, t32(0.95)))
    cmp("fp32 addcmul(U,Lr,value=-1) vs addcmul(U,-Lr)", X.addcmul(U, Lr, value=-1.0), X.addcmul(U, -Lr))
    cmp("fp32 addcmul(U,Lr,value=-1) vs X-U*Lr", X.addcmul(U, Lr, value=-1.0), X - U * Lr)
    cmp("fp32 addcmul(U,Lr,value=-1) vs X.sub(U*Lr)", X.addcmul(U, Lr, value=-1.0), X.sub(U * Lr))
    cmp("fp32 clamp_min(1e-7) float vs tensor", V.clamp_min(1e-7), V.clamp_min(t32(1e-7)))
    cmp("fp32 clamp_min(1e-7) float vs maximum", V.clamp_min(1e-7), torch.maximum(V, t32(1e-7)))
    cmp("fp32 1-Lr*0.01 float vs t32", 1.0 - Lr * 0.01, t32(1.0) - Lr * t32(0.01))
    cmp("fp32 Lr*0.02 float vs t32", Lr * 0.02, Lr * t32(0.02))
    cmp("fp32 EMA mul_add vs lerp (not required)", X.clone().mul_(0.99).add_(G, alpha=0.01), X.lerp(G, t32(0.01)))
    B = torch.randn(1024, 1024, generator=g).to(torch.bfloat16).to(device)
    for c in (3.4445, -4.775, 2.0315, 1.01, 0.5):
        cmp(f"bf16 B*{c} float vs t32", B * c, B * t32(c))
        cmp(f"bf16 B*{c} float vs tbf16", B * c, B * tbf(c))
    nrm = B.norm()
    cmp("bf16 B/(n*1.01+1e-6) float vs t32", B / (nrm * 1.01 + 1e-6), B / (nrm * t32(1.01) + t32(1e-6)))
    cmp("bf16 B/(n*1.01+1e-6) float vs tbf16", B / (nrm * 1.01 + 1e-6), B / (nrm * tbf(1.01) + tbf(1e-6)))
    xs = torch.randn(4, 256, 1024, generator=g)
    xs = (xs / xs.norm(dim=(-2, -1), keepdim=True)).to(torch.bfloat16).to(device)
    ca, cb, cc = 3.4445, -4.775, 2.0315
    xxt = xs @ xs.mT
    ref = ca * xs + (cb * xxt + cc * (xxt @ xxt)) @ xs
    alt32 = t32(ca) * xs + (t32(cb) * xxt + t32(cc) * (xxt @ xxt)) @ xs
    altbf = tbf(ca) * xs + (tbf(cb) * xxt + tbf(cc) * (xxt @ xxt)) @ xs
    alt32r = xs * t32(ca) + (xxt * t32(cb) + (xxt @ xxt) * t32(cc)) @ xs
    cmp("bf16 NS iter float vs t32 (const first)", ref, alt32)
    cmp("bf16 NS iter float vs t32 (const second)", ref, alt32r)
    cmp("bf16 NS iter float vs tbf16", ref, altbf)


def _sync_probe(device: torch.device, rank: int) -> None:
    """FF_SYNC_PROBE: time candidate calls on the host right after queuing ~100-300 ms of device work."""
    def ms(t: float) -> float:
        return 1000.0 * (time.monotonic() - t)

    g = torch.Generator().manual_seed(1234)
    a_cpu = (torch.randn(4096, 4096, generator=g) / 64).to(torch.bfloat16)
    a = a_cpu.to(device)

    def chain(n: int = 48):
        y = a
        for _ in range(n):
            y = y @ a
        return y

    def run(fn, barrier: bool = False):
        synchronize(device)
        if barrier:
            dist.barrier()
            synchronize(device)
        t = time.monotonic()
        y = chain()
        t_q = ms(t)
        t = time.monotonic()
        fn(y)
        t_op = ms(t)
        t = time.monotonic()
        synchronize(device)
        return t_q, t_op, ms(t)

    def report(tag: str, cases, barrier: bool) -> None:
        for _, fn in cases:
            run(fn, barrier)
        for name, fn in cases:
            vals = sorted((run(fn, barrier) for _ in range(3)), key=lambda v: v[1])
            q, op, rest = vals[1]
            if rank == 0:
                print(f"sync_probe {tag:6s} {name:26s} enqueue_chain={q:7.1f}ms  op={op:7.1f}ms  "
                      f"drain_after={rest:7.1f}ms  (chain total {q + op + rest:7.1f}ms)", flush=True)

    if dist.is_available() and dist.is_initialized():
        world = dist.get_world_size()
        small = torch.zeros(8, device=device)
        mine = torch.zeros(1 << 16, device=device)
        out = torch.zeros(world << 16, device=device)
        pending = []
        report("coll", [
            ("noop_all_ranks", lambda y: None),
            ("all_reduce_async_issue", lambda y: pending.append(dist.all_reduce(small, async_op=True))),
            ("all_reduce_async_wait", lambda y: dist.all_reduce(small, async_op=True).wait()),
            ("all_reduce_sync", lambda y: dist.all_reduce(small)),
            ("all_gather_into_tensor", lambda y: dist.all_gather_into_tensor(out, mine)),
        ], barrier=True)
        for h in pending:
            h.wait()
    if rank != 0:
        return
    s0 = torch.zeros((), device=device)
    s1 = torch.ones((), device=device)
    half = torch.tensor(0.5, device=device)
    dst = torch.empty(8, 1024, dtype=torch.int32, device=device)
    d2d_src = torch.zeros(8, 1024, dtype=torch.int32, device=device)
    h2d_src = torch.ones(8, 1024, dtype=torch.int32)
    big = torch.zeros(4096, 4096, dtype=torch.bfloat16, device=device)
    report("local", [
        ("noop", lambda y: None),
        ("device_op", lambda y: s0.add_(s1)),
        ("pyfloat_operand", lambda y: s0.mul_(0.5)),
        ("device_scalar_operand", lambda y: s0.mul_(half)),
        ("d2d_copy_", lambda y: dst.copy_(d2d_src)),
        ("h2d_copy_unrelated", lambda y: dst.copy_(h2d_src)),
        ("h2d_copy_big_unrelated", lambda y: big.copy_(a_cpu)),
        ("h2d_new_tensor", lambda y: torch.tensor(0.5, dtype=torch.float32).to(device)),
        ("h2d_copy_into_chain_input", lambda y: a.copy_(a_cpu)),
        ("item_calibration", lambda y: y[0, 0].item()),
    ], barrier=False)
