def ptp_prefix_table(enc) -> list:
    """FF_PTP_W: prefix[i] = id of the longest proper byte-prefix of token i that is itself an ordinary
    token, -1 for single-byte and special tokens (or when no proper prefix is a token). Host-side Python
    on the tiktoken Encoding, once, before the clock. Token bytes are unique (asserted), so prefix[i] != i:
    the column can repeat the t+2 / t+3 targets in a row, never the t+1 target."""
    special = {enc.encode_single_token(t) for t in enc.special_tokens_set}
    ids = {enc.decode_single_token_bytes(i): i for i in range(enc.n_vocab) if i not in special}
    assert len(ids) + len(special) == enc.n_vocab, "FF_PTP_W: two tokens share their bytes"
    prefix = []
    for i in range(enc.n_vocab):
        b = b"" if i in special else enc.decode_single_token_bytes(i)
        prefix.append(next((ids[b[:n]] for n in range(len(b) - 1, 0, -1) if b[:n] in ids), -1))
    return prefix


def mtp_weight_table() -> list:
    """FF_MTP: the loss weights (w1, w2, w3) of every stage, stage 0 first. Phase 1 fades w3 to 0,
    phase 2 fades w2 to 0, each in MTP_LEVELS stages valued at the linear fade's midpoint; the last
    stage is (w1, 0, 0). Python floats, used once to build the device tensors."""
    w1, w2, w3 = MTP_W
    n = MTP_LEVELS
    table = [(w1, w2, w3 * (1.0 - (j + 0.5) / n)) for j in range(n)]
    table += [(w1, w2 * (1.0 - (j + 0.5) / n), 0.0) for j in range(n)]
    table.append((w1, 0.0, 0.0))
    if PTP_W > 0.0:
        fade = [1.0] * n + [1.0 - (j + 0.5) / n for j in range(n)] + [0.0]
        table = [row + (PTP_W * f,) for row, f in zip(table, fade)]
    return table


def mtp_stage_of(progress: float) -> int:
    """FF_MTP: stage index for charged-time progress (charged / TIME_TARGET_SECONDS). Monotone
    non-decreasing, so the control all_reduce's MAX agrees with every rank's own clock."""
    p1, p2 = MTP_PHASES
    n = MTP_LEVELS
    if progress >= p2:
        return 2 * n
    if progress >= p1:
        return n + min(n - 1, int((progress - p1) / (p2 - p1) * n))
    return min(n - 1, int(max(0.0, progress) / p1 * n))


def mtp_weight_tensors(device: torch.device) -> list:
    """FF_MTP: one fp32 [3] tensor per stage on the device, each its OWN allocation (storage offset
    0, no aliasing), built once before the loop. They are copy SOURCES for mtp_weight_buffer's
    tensor and are never passed to the model: graph inputs of the compiled model must stay the
    same tensor objects."""
    return [torch.tensor(row, dtype=torch.float32).to(device) for row in mtp_weight_table()]


def mtp_weight_buffer(ws: list) -> torch.Tensor:
    """FF_MTP: the ONE fp32 [3] tensor the model ever receives as mtp_w. It is its own allocation
    and holds stage 0. A stage switch rewrites it with the D2D copy_ used here, so the loop's switch
    is an op already run once before the budget clock."""
    buf = torch.empty_like(ws[0])
    buf.copy_(ws[0])
    return buf
ACCUM_SCHED_RAW = os.environ.get("FF_ACCUM_SCHED", "1:0.06,2:0.2,4").strip()
