def accum_phase_of(next_step: int, progress: float) -> int:
    """FF_ACCUM_SCHED: the phase the update numbered next_step wants: 0 = the warm-up (k = K),
    1 = the k0 phase (LR x FF_ACCUM_LR), 2 = the rest of the run (k = K). progress = charged /
    FF_TIME_TARGET (0 before the clock restarts). Monotone non-decreasing in both arguments, so the
    control all_reduce's MAX never moves a rank back and every rank adopts the same phase on the
    same step. FF_ACCUM_FORCE_STEPS=a,b (diagnostic) sets both boundaries by step number.
    M12 FF_ACCUM_FROM: phase 0 ends at step ACCUM_FROM (WARMUP_STEPS unless set; still monotone)."""
    if ACCUM_FORCE_STEPS:
        a, b, *c = ACCUM_FORCE_STEPS
        return 0 if next_step < a else (1 if next_step < b else (2 if not c or next_step < c[0] else 3))
    if next_step < ACCUM_FROM:
        return 0
    if progress < ACCUM_UNTIL:
        return 1
    return 2 if ACCUM_UNTIL1 is None or progress < ACCUM_UNTIL1 else 3


def accum_k_of(phase: int, k_final: int) -> int:
    """FF_ACCUM_SCHED: micro-batches per update in a phase: k0 in phase 1, RAMP3's k1 in phase 2,
    otherwise K (k_final, grad_accum_steps)."""
    return ACCUM_K0 if phase == 1 else (ACCUM_K1 if phase == 2 and ACCUM_K1 is not None else k_final)


def accum_seed_tensors(loss: torch.Tensor, k_now: int):
    """FF_ACCUM_SCHED: (sources, buf). sources[k] = loss_seed(loss, k) for k0 and K: the tangent
    backward_scaled hands the backward at k micro-batches (ones_like / k, the same op, the same
    bits). They are copy SOURCES only. buf is the ONE tensor every training backward receives as
    its gradient: its own allocation, holding k_now's seed; a phase switch rewrites it with a
    device-to-device copy_. The seed is an input of the compiled backward graph, and graph inputs
    stay the same tensor objects (the mtp_weight_buffer rule)."""
    sources = {k: loss_seed(loss, k * _GPU_SHARES) for k in (ACCUM_K0, ACCUM_K1, ACCUM_K_FINAL) if k is not None}
    buf = torch.empty_like(sources[k_now])
    buf.copy_(sources[k_now])
    return sources, buf
