assert not (BF16_PARAMS and _IS_TRAINER) or os.environ.get("NEURON_RT_STOCHASTIC_ROUNDING_EN") is not None, (
    "FF_BF16_PARAMS is on but NEURON_RT_STOCHASTIC_ROUNDING_EN was never set: bf16 weight "
    "updates would round to nearest and the tail of the run would stop training")
# ==== train_gpu.py (P05): sharded-optimizer flags need torch.distributed world > 1; on one process rank 0
