def main() -> None:
    parser = argparse.ArgumentParser(description="FrontierForge training (v005-derived)")
    parser.add_argument("--device-type", "--device", dest="device_type", type=str, default="", choices=["", "cuda", "cpu"])
    parser.add_argument("--num-steps", type=int, default=int(os.environ.get("NEURON_COMPETITION_R1_NUM_STEPS", NUM_STEPS)))
    parser.add_argument("--max-train-seconds", type=int, default=int(os.environ.get("NEURON_COMPETITION_R1_MAX_TRAIN_SECONDS", MAX_TRAIN_SECONDS)))
    parser.add_argument("--out-dir", type=str, default=os.environ.get("NEURON_COMPETITION_R1_OUT_DIR", "out"))
    parser.add_argument("--eval-public", action=argparse.BooleanOptionalAction, default=os.environ.get("NEURON_COMPETITION_R1_EVAL_PUBLIC", "0") != "0")
    parser.add_argument("--eval-tokens", type=int, default=int(os.environ.get("NEURON_COMPETITION_R1_EVAL_TOKENS", str(4 * 524288))))
    parser.add_argument("--compile", type=str, default="inductor", choices=["inductor", "none"],
                        help="torch.compile the full model with inductor, or run eager (none)")
    parser.add_argument("--compile-only", action="store_true",
                        help="run one synthetic optimizer step to warm the compile cache, then exit")
    parser.add_argument("--nki-relu2", action="store_true", default=os.environ.get("NEURON_COMPETITION_R1_NKI_RELU2", "0") != "0",
                        help="use the example fused NKI relu(x)**2 kernel in the MLP (Neuron only; illustration)")
    _gpu_add_args(parser)
    args = _gpu_normalise_args(parser.parse_args())

    global USE_NKI_RELU2
    USE_NKI_RELU2 = args.nki_relu2
    assert not (USE_NKI_RELU2 and LEAKY_RELU2), (
        "FF_LEAKY_RELU2 replaces relu(x)**2, so the NKI relu**2 kernel (--nki-relu2 / "
        "NEURON_COMPETITION_R1_NKI_RELU2) would never run: set one or neither")
    assert not (USE_NKI_RELU2 and RELU2_FN), (
        "FF_RELU2_FN and the NKI relu**2 kernel (--nki-relu2 / NEURON_COMPETITION_R1_NKI_RELU2) are two "
        "different relu**2 paths: set one or neither")

    device_type = detect_device_type(args.device_type)
    ddp, rank, _local_rank, world_size, device = init_runtime(device_type)
    _gpu_after_init(args, world_size, rank, device)
    global COMPUTE_DTYPE
    COMPUTE_DTYPE = compute_dtype_for(device)

    print0(f"device={device} dtype={COMPUTE_DTYPE} world_size={world_size}")
    print0(
        f"schedule={SCHEDULE} time_target={TIME_TARGET_SECONDS}s num_steps={args.num_steps} "
        f"cooldown_fraction={COOLDOWN_FRACTION} bucket_allreduce={BUCKET_ALLREDUCE} "
        f"official_budget={TRAIN_TIME_BUDGET_SECONDS}s"
    )

    probes = diagnostic_probes()
    skip_save = SKIP_SAVE or bool(probes)
    if probes:
        print0(f"DIAGNOSTIC PROBE RUN ({', '.join(probes)}): the weights are garbage and no "
               f"checkpoint will be written; train_seq={TRAIN_SEQ}")

    tokenizer = ensure_tokenizer(build_if_missing=False)
    config = build_config()
    config.bos_id = tokenizer.get_bos_token_id()
    print0(f"model_config={json.dumps(config_dict(config), indent=2)}")
    if config.key_offset:
        ko = key_offset_mask(config).nonzero().flatten().tolist()
        print0(f"FF_KEY_OFFSET: {len(ko)} of {config.n_embd // config.n_head} key channels read position "
               f"t-1: {ko[0]}..{ko[len(ko) // 2 - 1]} and {ko[len(ko) // 2]}..{ko[-1]}")
    if softcap_offset_on(config):
        print0(f"FF_SOFTCAP_A/B: logits = {config.softcap_a or config.logit_softcap} * tanh((l + "
               f"{config.softcap_b}) / {config.logit_softcap}) at every head")
    if config.attn_proj_std > 0.0:
        print0(f"FF_ATTN_PROJ_STD: attention c_proj init uniform, std {config.attn_proj_std}, own generator "
               f"seed FF_SEED + {ATTN_PROJ_SEED_OFFSET:#x}")
    if config.xsa_layers:
        print0(f"FF_XSA_LAYERS: blocks {list(config.xsa_layers)} subtract tanh(alpha) * (<y,v>/<v,v>) * v after "
               f"attention; one 0-dim alpha each (init 0, scalar AdamW group). Numerics equal M9's until the "
               f"first update moves alpha: compare val_bpb.")
    if config.parallel_block:
        print0("FF_PARALLEL_BLOCK: every block computes x + attn(norm(x)) + mlp(norm(x)) from one shared norm "
               "of the lambda-mixed input; parameters and init are master's. Numerics differ from the first "
               "optimizer update on: compare val_bpb, and judge speed on charged_seconds_est_after_save.")
    if config.mlp_leaky:
        print0(f"FF_LEAKY_RELU2={config.mlp_leaky}: MLP activation leaky_relu(h, {config.mlp_leaky})**2 "
               f"({'in place' if LEAKY_INPLACE else 'out of place'}); no new parameters or RNG draws, and "
               f"c_proj starts at zero, so step 0's loss equals the flags-off control's")
    if RELU2_FN or (config.mlp_leaky and config.mlp_leaky_form in ("fn", "fnm")):
        print0(f"M12 activation: {'FF_RELU2_FN _Relu2Fn' if RELU2_FN else f'FF_LEAKY_FORM={config.mlp_leaky_form} _LeakySq'} "
               f"(an autograd.Function that saves s only; backward g * (s * 2.0))")
    if config.attn_src_layers or config.pool_last or CFC_INIT != 0.4:
        print0(f"M14: FF_ATTN_SRC={ATTN_SRC_RAW or 'off'} (blocks {list(config.attn_src_layers)} project q/k/v from "
               f"norm(x) saved after block {config.attn_src_after}; residual and MLP on x) | FF_POOL_LAST="
               f"{config.pool_last} (x += sum w_j * out_j, blocks "
               f"{list(range(config.n_layer - 1 - config.pool_last, config.n_layer - 1))}, 0-dim, init 0, scalar "
               f"AdamW) | FF_CFC_INIT={CFC_INIT} (c_fc init U(+-{CFC_INIT} * s))")
    model = GPT(config)
    model.init_weights()
    if BF16_PARAMS:
        n_bf16 = bf16_parameters_(model)
        print0(f"FF_BF16_PARAMS: {n_bf16} parameter tensors cast to bf16 (buffers unchanged); "
               f"optimizer states stay fp32; NEURON_RT_STOCHASTIC_ROUNDING_EN="
               f"{os.environ.get('NEURON_RT_STOCHASTIC_ROUNDING_EN', '<unset>')}; gradients are "
               f"bf16, so micro-batch accumulation and the all-reduce are bf16 "
               f"(FF_GRAD_BF16={GRAD_ALLREDUCE_BF16} is bypassed); runs are not bit-reproducible")
    if PTP_W > 0.0:
        prefix = ptp_prefix_table(tokenizer.enc)
        assert len(prefix) == config.vocab_size, f"FF_PTP_W: {len(prefix)} prefix ids for vocab {config.vocab_size}"
        model.register_buffer("ptp_prefix", torch.tensor(prefix, dtype=torch.float32).unsqueeze(1), persistent=False)
        print0(f"FF_PTP_W={PTP_W}: 4th MTP column = the t+1 target's longest proper byte-prefix token "
               f"({sum(v >= 0 for v in prefix)} of {len(prefix)} tokens have one, the rest are -1 = ignored); "
               f"weight {PTP_W} through MTP phase 1, faded with w2 in phase 2")
    model.to(device)
    mtp_ws = mtp_buf = None
    if MTP:
        mtp_ws = mtp_weight_tensors(device)
        mtp_buf = mtp_weight_buffer(mtp_ws)
        print0(f"FF_MTP={MTP}: loss = sum_k w_k * CE(next-token logits, target t+k), k = 1..3, weights "
               f"{MTP_W} fading (w3 by {MTP_PHASES[0]}, w2 by {MTP_PHASES[1]} of charged time) over "
               f"{len(mtp_ws)} stages: " + ", ".join("(" + ",".join(f"{v:g}" for v in r) + ")"
                                                    for r in mtp_weight_table())
               + ". The logged train loss is that weighted objective until the last stage: compare val_bpb.")
        if MTP_LOSS_NEXT or CE_ONEHOT:
            print0(f"patch_ce_head_lite: FF_MTP_LOSS_NEXT={int(MTP_LOSS_NEXT)} FF_CE_ONEHOT={CE_ONEHOT}: "
                   + ("the logged / NaN-checked train loss is the plain next-token CE (the gradient is still "
                      "the weighted MTP one); " if MTP_LOSS_NEXT else "")
                   + ("the MTP target gather / scatter_add is one dense [chunk, vocab] fp32 one-hot weighted "
                      "sum (exact at w = (1,0,0); duplicate targets round differently otherwise)" if CE_ONEHOT else ""))
    num_params = sum(p.numel() for p in model.parameters())
    flops_per_token = model.estimate_flops()
    print0(f"num_params={num_params:,} flops_per_token={flops_per_token:e}")

    orig_model = model
    acc_graph = None
    if ACC_IN_GRAPH and not args.compile:
        raise ValueError("FF_ACC_IN_GRAPH accumulates inside the COMPILED backward: it needs --compile "
                         "(NEURON_COMPETITION_R1_COMPILE=1)")
    if args.compile:
        compile_backend = "neuron" if device_type == "neuron" else "inductor"
        if ACC_IN_GRAPH:
            acc_graph = AccGraph(orig_model)
            model = torch.compile(acc_graph, backend=compile_backend, dynamic=False)
        else:
            model = torch.compile(model, backend=compile_backend, dynamic=False)
        print0(f"torch.compile enabled (backend={compile_backend})")

    world_tokens_per_micro = DEVICE_BATCH_SIZE * TRAIN_SEQ * _GPU_DATA_WORLD
    if TOTAL_BATCH_SIZE % world_tokens_per_micro != 0:
        raise ValueError(f"TOTAL_BATCH_SIZE={TOTAL_BATCH_SIZE} must divide micro tokens={world_tokens_per_micro}")
    grad_accum_steps = TOTAL_BATCH_SIZE // world_tokens_per_micro
    print0(f"micro_tokens={world_tokens_per_micro:,} grad_accum_steps={grad_accum_steps}")
    _gpu_check_grad_accum(grad_accum_steps)
    if ACCUM_SCHED_RAW:
        if ACCUM_K_FINAL != grad_accum_steps:
            raise ValueError(f"FF_ACCUM_SCHED={ACCUM_SCHED_RAW!r}: its last k ({ACCUM_K_FINAL}) must be grad_accum_steps "
                             f"({grad_accum_steps} = FF_TOTAL_BATCH / micro tokens)")
        if ACCUM_ON:
            print0(f"FF_ACCUM_SCHED={ACCUM_SCHED_RAW}: {ACCUM_K0} micro-batches per update "
                   f"({ACCUM_K0 * world_tokens_per_micro:,} tokens) with LR x {ACCUM_LR} "
                   + (f"from step {ACCUM_FORCE_STEPS[0]} to step {ACCUM_FORCE_STEPS[1] - 1} (FF_ACCUM_FORCE_STEPS, "
                      f"diagnostic)" if ACCUM_FORCE_STEPS else
                      f"from step {ACCUM_FROM} ("
                      + ("end of warm-up" if ACCUM_FROM == WARMUP_STEPS else
                         "FF_ACCUM_FROM: inside the LR warm-up, whose multiplier it scales")
                      + f") until {ACCUM_UNTIL} of charged time")
                   + f", {grad_accum_steps} ({TOTAL_BATCH_SIZE:,} tokens) otherwise; the Muon momentum ramp counts tokens")
            if ACCUM_K1 is not None:
                print0(f"FF_ACCUM_SCHED RAMP3: then {ACCUM_K1} micro-batches per update "
                       f"({ACCUM_K1 * world_tokens_per_micro:,} tokens) with LR x {ACCUM_LR1} "
                       + (f"to step {ACCUM_FORCE_STEPS[2] - 1}" if ACCUM_FORCE_STEPS else
                          f"until {ACCUM_UNTIL1} of charged time"))
        else:
            print0(f"FF_ACCUM_SCHED={ACCUM_SCHED_RAW}: one phase of {grad_accum_steps} micro-batches (the unflagged loop)")

    if args.compile_only or args.dry_run:
        synthetic_x = torch.zeros((DEVICE_BATCH_SIZE, TRAIN_SEQ), dtype=torch.int32).to(device)
        synthetic_y = torch.zeros((DEVICE_BATCH_SIZE, TRAIN_SEQ), dtype=torch.long).to(device)
        optimizer = model.setup_optimizer() if acc_graph is None else orig_model.setup_optimizer()
        acc_ctl = None if acc_graph is None else AccInGraph(acc_graph, orig_model, optimizer, device)
        model.zero_grad(set_to_none=True)
        for micro in range(grad_accum_steps * _GPU_SHARES):
            if acc_ctl is not None:
                loss = acc_ctl.micro(model, synthetic_x, synthetic_y, micro, mtp_buf)
            else:
                loss = model(synthetic_x, synthetic_y) if mtp_buf is None else model(synthetic_x, synthetic_y, mtp_w=mtp_buf)
            backward_scaled(loss, grad_accum_steps * _GPU_SHARES)
        sync_gradients(model)
        optimizer.step()
        synchronize(device)
        print0("compile-only synthetic training step completed")
        if args.dry_run:
            _gpu_dry_run(model, acc_ctl, optimizer, synthetic_x, synthetic_y, mtp_buf, grad_accum_steps, device, args)
        cleanup_runtime()
        return

    train_loader = None
    if STREAM_MIX:
        assert STREAM_ROWS, "FF_STREAM_MIX requires FF_STREAM_ROWS=1"
        train_loader = _gpu_make_loader(make_train_stream_loader, tokenizer, DEVICE_BATCH_SIZE, TRAIN_SEQ, device, grad_accum_steps)
        x, y, loader_state = next(train_loader)
        print0(f"train loader: stream rows, {STREAM_MIX} independent streams (no fallback)")
    elif STREAM_ROWS:
        try:
            train_loader = _gpu_make_loader(make_train_stream_loader, tokenizer, DEVICE_BATCH_SIZE, TRAIN_SEQ, device, grad_accum_steps)
            x, y, loader_state = next(train_loader)
            print0("train loader: stream rows (evaluator layout)")
        except Exception as exc:
            print0(f"stream loader failed ({exc!r}); using make_dataloader")
            train_loader = None
    if train_loader is None:
        if MASK_BOS_TARGET:
            train_loader = _gpu_make_loader(make_masked_packed_loader, tokenizer, DEVICE_BATCH_SIZE, TRAIN_SEQ, device)
        else:
            train_loader = _gpu_make_loader(make_dataloader, tokenizer, DEVICE_BATCH_SIZE, TRAIN_SEQ, "train", device)
        x, y, loader_state = next(train_loader)
    if MASK_BOS_TARGET:
        print0(f"FF_MASK_BOS_TARGET=1: training targets equal to the BOS id ({tokenizer.get_bos_token_id()}) "
               f"are -1 (ignored); inputs, the model and the evaluator are unchanged. The logged train "
               f"loss is the mean over the remaining targets: compare val_bpb.")
    optimizer = orig_model.setup_optimizer()
    async_sync = AsyncGradSync(orig_model) if (ASYNC_SYNC and ddp) else None
    acc_ctl = None if acc_graph is None else AccInGraph(acc_graph, orig_model, optimizer, device)
    print0(f"async_sync={'on' if async_sync else 'off'} foreach_adamw={FOREACH_ADAMW} loss_chunk={LOSS_CHUNK} "
           f"fused_ce={FUSED_CE} manual_attention={MANUAL_ATTENTION}")
    if CE_BF16:
        assert COMPUTE_DTYPE == torch.bfloat16, f"FF_CE_BF16 needs the bf16 compute dtype, not {COMPUTE_DTYPE}"
        print0("FF_CE_BF16=1: the fused head's tanh / log_softmax / exp / scatter / 1 - th^2 chain runs in "
               "bf16; the loss sum and the grad_w accumulator stay fp32. Numerics differ from step 0: "
               "compare val_bpb, and judge speed on charged_seconds_est_after_save.")
    if POS_WEIGHT_ON:
        print0(f"FF_POS_WEIGHT={POS_WEIGHT} on the first {POS_WEIGHT_N} positions of every row: the "
               f"TRAINING objective is a weighted mean, so the logged loss is that weighted mean and "
               f"is NOT comparable with an unflagged run's. Compare val_bpb only. The evaluator, the "
               f"model and model_config are unchanged.")
    live_params = [q for q in orig_model.parameters()]
    if COMPILE_OPT:
        compiled_opt_step = torch.compile(optimizer.step, backend="neuron", dynamic=False)
        print0("optimizer step will run compiled from step 1")
    ema_state: dict = {}
    if OPT_FUSE and USE_EMA:
        ema_params = ema_fuse_build(live_params, optimizer, ema_state)
    else:
        ema_params = [q.detach().clone().float() for q in live_params] if USE_EMA else None
    ema_steps = 0
    insurance_saved = False
    insurance_next = 0
    checkpoint_path = Path(args.out_dir) / "final.pt"
    print0(f"ema={'on' if USE_EMA else 'off'} decay={EMA_DECAY} every={EMA_EVERY} save_ema_above_level={EMA_SAVE_MAX_LEVEL} insurance_at={INSURANCE_AT}"
           + (f" prewarm_step={TRAIN_STARTUP_STEPS_EXCLUDED - 2}" if EMA_PREWARM else ""))
    prof = None
    if PROFILE_TRACE and rank == 0:
        from torch.profiler import ProfilerActivity, profile, schedule
        exp_cfg = None
        try:
            from torch_neuronx.profiling import NeuronConfig
            exp_cfg = NeuronConfig(profile_output_dir=str(Path(args.out_dir) / "nrt_profile"),
                                   neff_cache_dir=os.environ.get("TORCH_NEURONX_NEFF_CACHE_DIR", "/tmp/neff_cache"))
        except Exception as exc:
            print0(f"NeuronConfig unavailable ({exc}); CPU/device op trace only")
        acts = [ProfilerActivity.CPU]
        if hasattr(ProfilerActivity, "PrivateUse1"):
            acts.append(ProfilerActivity.PrivateUse1)
        prof = profile(activities=acts, schedule=schedule(wait=6, warmup=1, active=2, repeat=1),
                       experimental_config=exp_cfg, with_stack=PROFILE_STACK)
        prof.start()
    loop_started = time.monotonic()
    budget_started = loop_started

    smooth_loss = 0.0
    total_train_tokens = 0
    step = 0
    recent_step_times: list[float] = []
    steady_step_times: list[float] = []
    phase_totals = [0.0, 0.0, 0.0]
    phase_count = 0
    startup_allowance_est = 0.0
    next_level = 20
    applied_level = 20
    last_logged_level = 20
    hs_last_t = None
    hs_last_step = -1
    lr_cache = {}
    mtp_stage = 0
    mtp_switches = []
    accum_phase = accum_phase_of(0, 0.0) if ACCUM_ON else 0
    accum_k = accum_k_of(accum_phase, grad_accum_steps)
    accum_seeds = accum_seed_buf = None
    accum_micro_done = 0
    accum_switches = []
    accum_steps_by_k: dict = {}
    accum_dts: dict = {}

    while step < args.num_steps:
        hs = (not ASYNC_LOOP or step + 1 <= TRAIN_STARTUP_STEPS_EXCLUDED
              or (step + 1) % ASYNC_LOOP == 0 or step + 1 >= args.num_steps)
        if not ASYNC_LOOP:
            synchronize(device)
        t0 = time.monotonic()
        if acc_ctl is not None:
            acc_ctl.begin_step()
        optimizer.zero_grad(set_to_none=True)
        last_loss = None
        step_k = accum_k
        micro_n = step_k * _GPU_SHARES
        _gpu_loader_set_k(train_loader, step_k)
        step_tokens = TOTAL_BATCH_SIZE if not ACCUM_ON else step_k * world_tokens_per_micro
        for micro in range(micro_n):
            if HOST_TIMES:
                _t = time.monotonic()
            if acc_ctl is not None:
                loss = acc_ctl.micro(model, x, y, micro, mtp_buf)
            else:
                loss = model(x, y) if mtp_buf is None else model(x, y, mtp_w=mtp_buf)
            if HOST_TIMES:
                _ht_add("forward", _t)
            last_loss = loss.detach()
            if async_sync is not None and micro == micro_n - 1:
                async_sync.arm()
            if HOST_TIMES:
                _t = time.monotonic()
            if ACCUM_ON:
                if accum_seed_buf is None:
                    accum_seeds, accum_seed_buf = accum_seed_tensors(loss, step_k)
                loss.backward(gradient=accum_seed_buf)
            else:
                backward_scaled(loss, grad_accum_steps * _GPU_SHARES)
            if HOST_TIMES:
                _ht_add("backward", _t)
                _t = time.monotonic()
            if not LATE_FETCH or micro < micro_n - 1:
                x, y, loader_state = next(train_loader)
            if HOST_TIMES:
                _ht_add("loader", _t)
        if PROFILE or (args.compile and COMPILE_SYNC):
            synchronize(device)
        t_backward = time.monotonic()

        _dtrace = _DispatchTrace() if (DISPATCH_TRACE and step == 7 and rank == 0) else None
        if _dtrace is not None:
            _dtrace.__enter__()
        if GRAD_CLIP > 0:
            torch.nn.utils.clip_grad_norm_(model.parameters(), GRAD_CLIP)
        if async_sync is not None:
            if HOST_TIMES:
                _t = time.monotonic()
            async_sync.finish()
            if HOST_TIMES:
                _ht_add("grad_finish", _t)
        else:
            sync_gradients(orig_model)
        if args.compile and COMPILE_SYNC:
            synchronize(device)
        if PROFILE:
            synchronize(device)
        t_reduce = time.monotonic()

        if SCHEDULE == "time":
            lrm = (step + 1) / WARMUP_STEPS if step < WARMUP_STEPS else next_level / 20
        else:
            lrm = lr_multiplier_steps(step)
        applied_level = max(1, min(20, round(lrm * 20)))
        muon_wd = WEIGHT_DECAY if (WD_SCHED == 0.0 or step < WARMUP_STEPS) else WEIGHT_DECAY * lrm ** WD_SCHED
        accum_lr = ACCUM_LR1 if step_k == ACCUM_K1 else ACCUM_LR
        if ACCUM_ON and step_k != grad_accum_steps and accum_lr != 1.0:
            lrm = lrm * accum_lr
        muon_mom = muon_momentum(step) if not ACCUM_ON else muon_momentum(accum_micro_done / grad_accum_steps)
        if LIT:
            muon_mom -= 0.05 * (20 - next_level) / 19
        if MOM_CD_LEVELS and next_level <= MOM_CD_LEVELS:
            muon_mom += (MOM_CD_FLOOR - muon_mom) * (MOM_CD_LEVELS + 1 - next_level) / MOM_CD_LEVELS
        if TENSOR_LR and (ASYNC_LOOP or SCALAR_CONSTS):
            lr_t = lr_cache.get(lrm)
            if lr_t is None:
                lr_t = lr_cache[lrm] = torch.tensor(lrm, dtype=torch.float32).to(device)
        else:
            lr_t = torch.tensor(lrm, dtype=torch.float32).to(device) if TENSOR_LR else None
        lrm_a = lrm if ADAMW_LR_POW == 1.0 else lrm ** ADAMW_LR_POW
        if ASYNC_OPT and ADAMW_LR_POW != 1.0:
            lr_t_a = lr_cache.get(("adamw", lrm_a))
            if lr_t_a is None:
                lr_t_a = lr_cache[("adamw", lrm_a)] = torch.tensor(lrm_a, dtype=torch.float32).to(device)
        else:
            lr_t_a = lr_t if ADAMW_LR_POW == 1.0 else (
                torch.tensor(lrm_a, dtype=torch.float32).to(device) if TENSOR_LR else None)
        mom_t = torch.tensor(muon_mom, dtype=torch.float32).to(device) if COMPILE_OPT else None
        step_t = torch.tensor(float(step + 1), dtype=torch.float32).to(device) if COMPILE_OPT else None
        for group in optimizer.param_groups:
            muon = group["kind"] == "muon"
            group["lr"] = group["initial_lr"] * (lrm if muon else lrm_a)
            group["lr_t"] = lr_t if muon else lr_t_a
            group["momentum_t"] = mom_t
            group["step_t"] = step_t
            if group["kind"] == "muon":
                group["momentum"] = muon_mom
                group["weight_decay"] = muon_wd
        if HOST_TIMES:
            _t_opt = time.monotonic()
        if COMPILE_OPT and step >= 1:
            compiled_opt_step()
        else:
            optimizer.step()
        if HOST_TIMES:
            _ht_add("optimizer_step", _t_opt)
        if ema_params is not None and ((step + 1) % EMA_EVERY == 0
                                       or (EMA_PREWARM and step + 1 == TRAIN_STARTUP_STEPS_EXCLUDED - 1)):
            if MUON_ZERO2:
                optimizer.muon_zero2_gather_()
            ema_update(ema_params, live_params, ema_state)
            ema_steps += 1
        if _dtrace is not None:
            _dtrace.__exit__(None, None, None)
        if LATE_FETCH:
            if HOST_TIMES:
                _t = time.monotonic()
            x, y, loader_state = next(train_loader)
            if HOST_TIMES:
                _ht_add("late_fetch", _t)
        if SYNC_PROBE and step == 7:
            _sync_probe(device, rank)
        if SYNC_PROBE2 and step == 7 and rank == 0:
            _sync_probe2(device)

        if hs:
            if HOST_TIMES:
                _t = time.monotonic()
            synchronize(device)
            if HOST_TIMES:
                _ht_add("hs_wait", _t)
        record_step_boundary(step)
        if HOST_TIMES and hs and rank == 0:
            n_int = max(1, step - (hs_last_step if ASYNC_LOOP and hs_last_step is not None else step - 1))
            parts = " ".join(f"{k}={1000 * v / n_int:.1f}ms" for k, v in sorted(_HT.items()))
            print(f"host_times step {step:05d} per-step over {n_int}: {parts}", flush=True)
            _HT.clear()
        if prof is not None:
            prof.step()
        t_end = time.monotonic()
        dt = t_end - t0
        if _GPU_VCLOCK is not None:
            _GPU_VCLOCK.record(step, step_k)
        if ASYNC_LOOP:
            if hs:
                n_hs = step - hs_last_step
                per = (t_end - hs_last_t) / n_hs if hs_last_t is not None and n_hs > 0 else dt
                for s_ in range(hs_last_step + 1, step + 1):
                    recent_step_times.append(per)
                    if s_ >= 3:
                        steady_step_times.append(per)
                hs_last_t, hs_last_step = t_end, step
                dt = per
        else:
            recent_step_times.append(dt)
        if step >= 3 and not ASYNC_LOOP:
            steady_step_times.append(dt)
            if PROFILE:
                phase_totals[0] += t_backward - t0
                phase_totals[1] += t_reduce - t_backward
                phase_totals[2] += t_end - t_reduce
                phase_count += 1
        if ACCUM_ON:
            accum_steps_by_k[step_k] = accum_steps_by_k.get(step_k, 0) + 1
            if step >= 3 and not ASYNC_LOOP:
                accum_dts.setdefault(step_k, []).append(dt)
        if hs:
            train_loss = float(last_loss.item())
        if step + 1 == TRAIN_STARTUP_STEPS_EXCLUDED:
            now = time.monotonic()
            observed_startup = now - _PROCESS_STARTED
            startup_allowance_est = min(observed_startup, TRAIN_STARTUP_ALLOWANCE_CAP_SECONDS)
            excess = max(
                0.0,
                observed_startup + STARTUP_LAUNCH_MARGIN_SECONDS - TRAIN_STARTUP_ALLOWANCE_CAP_SECONDS,
            )
            budget_started = now - excess

        reached_min_steps = step + 1 >= TRAIN_STARTUP_STEPS_EXCLUDED
        charged_wall = time.monotonic() - budget_started
        charged = _GPU_VCLOCK.charged if _GPU_VCLOCK is not None else charged_wall
        if SCHEDULE == "time":
            level_next = cooldown_level(charged / TIME_TARGET_SECONDS) if reached_min_steps else 20
            stop_after_step = step + 1 >= args.num_steps or (
                reached_min_steps and not _GPU_STOP_PINNED
                and (
                    charged >= TIME_TARGET_SECONDS
                    or charged + (max(1, ASYNC_LOOP) if len(steady_step_times) >= 5 else 1)
                    * step_time_estimate(*_gpu_est_windows(recent_step_times, steady_step_times))
                    + CHECKPOINT_RESERVE_SECONDS >= TIME_TARGET_SECONDS
                )
            )
            if _GPU_ARGS.wall_cap and time.monotonic() - loop_started > _GPU_ARGS.wall_cap:
                raise RuntimeError("train_gpu.py: --wall-cap %.0fs exceeded at step %d" % (_GPU_ARGS.wall_cap, step))
            insurance_due = (
                not skip_save and reached_min_steps and insurance_next < len(INSURANCE_AT)
                and charged / TIME_TARGET_SECONDS >= INSURANCE_AT[insurance_next]
            )
        else:
            level_next = 20
            insurance_due = False
            stop_after_step = step + 1 >= args.num_steps or (
                reached_min_steps
                and (
                    time.monotonic() - _PROCESS_STARTED >= args.max_train_seconds
                    or time.monotonic() - _PROCESS_STARTED
                    + max(recent_step_times[-20:])
                    + CHECKPOINT_RESERVE_SECONDS
                    >= args.max_train_seconds
                )
            )
        mtp_stage_next = mtp_stage_of(charged / TIME_TARGET_SECONDS) if (MTP and reached_min_steps) else 0
        accum_phase_next = accum_phase_of(
            step + 1, charged / TIME_TARGET_SECONDS if reached_min_steps else 0.0) if ACCUM_ON else 0
        control = None if not hs else torch.tensor(
            [
                1 if (math.isnan(train_loss) or train_loss > 100) else 0,
                1 if stop_after_step else 0,
                level_next,
                1 if insurance_due else 0,
            ] + ([mtp_stage_next] if MTP else []) + ([accum_phase_next] if ACCUM_ON else []),
            dtype=torch.int32,
        ).to(device)
        if hs:
            if dist.is_available() and dist.is_initialized():
                dist.all_reduce(control, op=dist.ReduceOp.MAX)
            bad_loss, stop_flag, next_level, insurance_flag, *mtp_got = (int(v) for v in control.tolist())
            accum_got = mtp_got.pop() if ACCUM_ON else 0
            if next_level != _GPU_LEVEL_LAST[0]:
                _GPU_LEVEL_SWITCHES.append([next_level, step + 1, round(charged, 1)])
                _GPU_LEVEL_LAST[0] = next_level
            if mtp_got and mtp_got[0] != mtp_stage:
                mtp_buf.copy_(mtp_ws[mtp_got[0]])
                mtp_switches.append([mtp_got[0], step + 1, round(charged, 1)])
                if rank == 0:
                    print(f"FF_MTP stage {mtp_got[0]}/{2 * MTP_LEVELS}: loss weights "
                          f"{tuple(round(v, 6) for v in mtp_weight_table()[mtp_got[0]])} from step {step + 1} "
                          f"(charged {charged:.0f}s)", flush=True)
                mtp_stage = mtp_got[0]
            if ACCUM_ON and accum_got > accum_phase:
                k_new = accum_k_of(accum_got, grad_accum_steps)
                if k_new != accum_k:
                    accum_seed_buf.copy_(accum_seeds[k_new])
                accum_switches.append([accum_got, step + 1, round(charged, 1), k_new])
                if rank == 0:
                    print(f"FF_ACCUM_SCHED phase {accum_got}: {k_new} micro-batches per update "
                          f"({k_new * world_tokens_per_micro:,} tokens) from step {step + 1} "
                          f"(charged {charged:.0f}s)", flush=True)
                accum_phase, accum_k = accum_got, k_new
        else:
            bad_loss, stop_flag, insurance_flag = 0, 0, 0
        if bad_loss:
            raise RuntimeError(f"bad loss detected: {train_loss}")
        if insurance_flag and not stop_flag:
            insurance_saved = True
            insurance_next += 1
            use_ema = ema_params is not None and applied_level > EMA_SAVE_MAX_LEVEL
            if MUON_ZERO2:
                optimizer.muon_zero2_gather_()
            if rank == 0:
                t_ins = time.monotonic()
                save_payload_atomic(checkpoint_path, checkpoint_payload(orig_model, ema_params, use_ema, {
                    "step": step + 1, "total_train_tokens": total_train_tokens + step_tokens,
                    "insurance": True, "saved_weights": "ema" if use_ema else "trained",
                    "level": applied_level, "ema_steps": ema_steps, "world_size": world_size,
                }))
                print(f"insurance checkpoint ({'ema' if use_ema else 'trained'}, level {applied_level}) "
                      f"written in {time.monotonic() - t_ins:.1f}s at charged {charged:.0f}s", flush=True)

        total_train_tokens += step_tokens
        accum_micro_done += step_k
        smooth_loss = 0.9 * smooth_loss + 0.1 * train_loss
        debiased = smooth_loss / (1 - 0.9 ** (step + 1))
        tok_per_sec = step_tokens / max(dt, 1e-6)
        if rank == 0 and ((not ASYNC_LOOP and (step < 5 or step % 10 == 0
                                              or next_level != last_logged_level or stop_flag))
                          or (ASYNC_LOOP and hs)):
            last_logged_level = next_level
            phases = ""
            if PROFILE:
                phases = f" | fb {t_backward - t0:.3f}s ar {t_reduce - t_backward:.3f}s opt {t_end - t_reduce:.3f}s"
            print(
                f"step {step:05d} | loss {debiased:.4f} | lrm {lrm:.3f} | dt {dt:.2f}s | "
                f"tok/s {tok_per_sec:,.0f} | charged {charged:.0f}s | next_level {next_level}{phases}{_gpu_wall_tag(charged_wall)}",
                flush=True,
            )

        if acc_ctl is not None and rank == 0 and step == 0:
            print(f"FF_ACC_IN_GRAPH after step 0: {json.dumps(acc_ctl.dynamo_stats(), sort_keys=True)}", flush=True)
        if step == 0:
            gc.collect()
            gc.freeze()
            gc.disable()
        step += 1
        if stop_flag:
            break

    if prof is not None:
        prof.stop()
        for key in ("self_device_time_total", "self_cpu_time_total"):
            try:
                print(f"===== profile: top ops by {key} =====", flush=True)
                print(prof.key_averages().table(sort_by=key, row_limit=45), flush=True)
                break
            except Exception as exc:
                print(f"profile table by {key} failed: {exc}", flush=True)
        if PROFILE_STACK:
            want = ("aten::item", "aten::_local_scalar_dense", "neuron::copy::cpu_to_neuron",
                    "neuron::copy::neuron_to_cpu", "aten::_to_copy")
            try:
                rows = [e for e in prof.key_averages(group_by_stack_n=12) if e.key in want]
                rows.sort(key=lambda e: -e.count)
                print("===== profile: host<->device sync/copy call sites, 2 active steps, by count =====", flush=True)
                for e in rows[:80]:
                    frames = list(e.stack or [])
                    mine = [f for f in frames if "train_ff" in f or "prepare.py" in f]
                    shown = (mine or frames)[:6]
                    print(f"{e.count:6d}  {e.key:30s}  " + "  <-  ".join(shown), flush=True)
            except Exception as exc:
                print(f"profile stack grouping failed: {exc}", flush=True)
        try:
            prof.export_chrome_trace(str(Path(args.out_dir) / "trace.json"))
        except Exception as exc:
            print(f"trace export failed: {exc}", flush=True)
    budget_elapsed_before_save = time.monotonic() - budget_started
    final_use_ema = ema_params is not None and applied_level > EMA_SAVE_MAX_LEVEL
    saved_weights = "ema" if final_use_ema else "trained"
    if MUON_ZERO2:
        optimizer.muon_zero2_gather_()
    blend_on = bool(EMA_BLEND) and ema_params is not None and not final_use_ema
    if blend_on and EMA_DECAY_EFF ** ema_steps > EMA_BLEND_MAX_INIT:
        print0(f"FF_EMA_BLEND={EMA_BLEND:g}: only {ema_steps} EMA update(s), the init weights still hold "
               f"{EMA_DECAY_EFF ** ema_steps:.3f} of the EMA (> {EMA_BLEND_MAX_INIT}): saving the trained weights")
        blend_on = False
    if blend_on:
        saved_weights = f"blend:{EMA_BLEND:g}" + (":skip_emb" if EMA_BLEND_SKIP_EMB else "")
    final_blend = None
    if rank == 0 and not skip_save:
        final_payload = checkpoint_payload(orig_model, ema_params, final_use_ema, {
            "step": step,
            "total_train_tokens": total_train_tokens,
            "budget_elapsed_before_save": budget_elapsed_before_save,
            "world_size": world_size,
            "compiled": args.compile,
            "saved_weights": saved_weights,
            "final_level": applied_level,
            "ema_steps": ema_steps,
            "insurance_was_written": insurance_saved,
            **({"accum_sched": ACCUM_SCHED_RAW, "accum_lr": ACCUM_LR_LOG} if ACCUM_ON else {}),
            **({"accum_from": ACCUM_FROM} if ACCUM_FROM != WARMUP_STEPS else {}),
        })
        if blend_on:
            final_blend = ema_blend_host(orig_model, ema_params, EMA_BLEND, EMA_BLEND_SKIP_EMB,
                                         trained=final_payload["model_state"])
            final_payload["model_state"].update(final_blend)
        save_payload_atomic(checkpoint_path, final_payload)
        del final_payload
        print(f"final checkpoint: {saved_weights} weights (last applied level {applied_level}, ema_steps {ema_steps})", flush=True)
    if final_use_ema:
        with torch.no_grad():
            for q, e in zip(live_params, ema_params):
                q.copy_(e.detach().cpu().to(q.dtype) if q.dtype != torch.float32 else e.to(q.dtype))
    if dist.is_available() and dist.is_initialized():
        dist.barrier()
    budget_elapsed_after_save = time.monotonic() - budget_started
    if EMA_EVAL and rank == 0 and not skip_save and ema_params is not None:
        t_ema = time.monotonic()
        ema_path = checkpoint_path.with_name("ema.pt")
        save_payload_atomic(ema_path, checkpoint_payload(orig_model, ema_params, True, {
            "step": step,
            "total_train_tokens": total_train_tokens,
            "world_size": world_size,
            "compiled": args.compile,
            "saved_weights": "ema",
            "final_level": applied_level,
            "ema_steps": ema_steps,
            "ema_eval": True,
        }))
        print(f"ema checkpoint: {ema_path} written in {time.monotonic() - t_ema:.1f}s", flush=True)

    if blend_on and (args.eval_public or config.xsa_layers):
        if final_blend is None:
            final_blend = ema_blend_host(orig_model, ema_params, EMA_BLEND, EMA_BLEND_SKIP_EMB)
        with torch.no_grad():
            live = dict(orig_model.named_parameters())
            for name, q in live.items():
                if name in final_blend:
                    q.copy_(final_blend[name].to(q.device))
            chk = next((n for n in final_blend if live[n].storage_offset() != 0), next(iter(final_blend)))
            if not torch.equal(live[chk].detach().cpu(), final_blend[chk]):
                raise RuntimeError(f"FF_EMA_BLEND: the copy-back of {chk} does not read back as the saved weights")
        del live
    public_eval = None
    causal = None
    _gpu_t_eval = time.monotonic()
    if args.eval_public and not probes:
        if args.causality_check:
            causal = causality_check(orig_model, tokenizer, DEVICE_BATCH_SIZE, SEQ_LEN, device)
        public_eval = _gpu_score(orig_model, tokenizer, device, args)
        print0("val_bpb=%.6f over %s tokens / %s bytes (%s) in %.1fs" % (
            public_eval["val_bpb"], format(public_eval["num_tokens"], ","), format(public_eval["num_bytes"], ","),
            public_eval["eval_ranks_how"], time.monotonic() - _gpu_t_eval))
    _gpu_eval_seconds = time.monotonic() - _gpu_t_eval

    if rank == 0:
        median_dt = sorted(steady_step_times)[len(steady_step_times) // 2] if steady_step_times else float("nan")
        summary = {
            "schedule": SCHEDULE,
            "time_target_seconds": TIME_TARGET_SECONDS,
            "cooldown_fraction": COOLDOWN_FRACTION,
            "depth": config.n_layer,
            "width": config.n_embd,
            "microbatch": DEVICE_BATCH_SIZE,
            "total_batch": TOTAL_BATCH_SIZE,
            "grad_accum_steps": grad_accum_steps,
            "bucket_allreduce": BUCKET_ALLREDUCE,
            "compiled": args.compile,
            "seed": SEED,
            "warmup_steps": WARMUP_STEPS,
            "adamw_lr_scale": ADAMW_LR_SCALE,
            "matrix_lr_scale": MATRIX_LR_SCALE,
            "steps": step,
            "total_tokens": total_train_tokens,
            "num_params": num_params,
            "training_seconds_before_save": round(budget_elapsed_before_save, 1),
            "charged_seconds_est_after_save": round(budget_elapsed_after_save, 1),
            "startup_allowance_est": round(startup_allowance_est, 1),
            "median_step_seconds": round(median_dt, 4),
            "tokens_per_second": round(TOTAL_BATCH_SIZE / median_dt) if steady_step_times else None,
            "final_smoothed_loss": round(smooth_loss / (1 - 0.9 ** max(step, 1)), 4),
            "checkpoint": None if skip_save else str(checkpoint_path),
            "ema_decay": EMA_DECAY if USE_EMA else None,
            "saved_weights": saved_weights,
            "final_level": applied_level,
            "insurance_saved": insurance_saved,
        }
        if MTP:
            summary["mtp"] = {"mode": MTP, "weights": list(MTP_W), "phases": list(MTP_PHASES),
                              "levels": MTP_LEVELS, "final_stage": mtp_stage, "switches": mtp_switches}
            if PTP_W > 0.0:
                summary["mtp"]["ptp_w"] = PTP_W
            if MTP_LOSS_NEXT or CE_ONEHOT:
                summary["mtp"]["ce_head_lite"] = {"loss_next": MTP_LOSS_NEXT, "onehot": CE_ONEHOT}
        if ACCUM_ON:
            summary["accum_sched"] = {
                "schedule": ACCUM_SCHED_RAW, "lr_scale": ACCUM_LR_LOG, "force_steps": list(ACCUM_FORCE_STEPS) or None,
                "switches": accum_switches, "final_k": accum_k,
                "steps_by_k": {str(k): n for k, n in sorted(accum_steps_by_k.items())},
                **({"from_step": ACCUM_FROM} if ACCUM_FROM != WARMUP_STEPS else {}),
                "median_step_seconds_by_k": {str(k): round(sorted(v)[len(v) // 2], 4)
                                             for k, v in sorted(accum_dts.items())},
            }
        if MASK_BOS_TARGET:
            summary["mask_bos_target"] = True
        if config.xsa_layers:
            summary["xsa_tanh_alpha"] = {str(i): round(math.tanh(float(orig_model.transformer.h[i].attn.xsa)), 4)
                                         for i in config.xsa_layers}
        if config.attn_src_layers or config.pool_last or CFC_INIT != 0.4:
            summary["m14"] = {"attn_src": ATTN_SRC_RAW or None, "pool_last": config.pool_last, "cfc_init": CFC_INIT,
                              **({"pool_w": [round(float(w), 5) for w in orig_model.pool_w]}
                                 if orig_model.pool_w is not None else {})}
        if acc_ctl is not None:
            summary["acc_in_graph"] = acc_ctl.summary()
        if probes:
            summary["diagnostic_probe"] = probes
        if PROFILE and phase_count:
            summary["mean_phase_seconds"] = {
                "forward_backward": round(phase_totals[0] / phase_count, 4),
                "allreduce": round(phase_totals[1] / phase_count, 4),
                "optimizer_and_sync": round(phase_totals[2] / phase_count, 4),
            }
        if PHASE_PROFILE and step:
            summary["forward_phase_seconds_per_step"] = {
                name: round(total / step, 4) for name, total in sorted(PHASE_TIMES.items())
            }
        if causal is not None:
            summary["causality_passed"] = causal["passed"]
        if public_eval is not None:
            summary["public_val_bpb"] = public_eval["val_bpb"]
        print("ff_summary: " + json.dumps(summary, sort_keys=True), flush=True)
        _gpu_write_results(args, summary, public_eval, causal, _gpu_eval_seconds, device, config)

    cleanup_runtime()


if __name__ == "__main__":
    main()
